import pandas as pd
import numpy as np


def _weekly_expiries_8utc(idx: pd.DatetimeIndex) -> pd.DatetimeIndex:
    """Every Friday 08:00 UTC present within the index's calendar span (Deribit weekly/monthly settlement hour)."""
    if len(idx) == 0:
        return pd.DatetimeIndex([])
    start = idx.min().normalize() - pd.Timedelta(days=7)
    end = idx.max().normalize() + pd.Timedelta(days=7)
    fridays = pd.date_range(start=start, end=end, freq="W-FRI", tz=idx.tz)
    return fridays + pd.Timedelta(hours=8)


def signals(df: pd.DataFrame) -> pd.Series:
    idx = df.index
    close = df["close"]
    sma = close.rolling(120, min_periods=120).mean()
    dev = (close - sma) / sma

    out = pd.Series(0, index=idx, dtype=int)
    for exp in _weekly_expiries_8utc(idx):
        window_start = exp - pd.Timedelta(hours=24)
        mask = (idx >= window_start) & (idx < exp)
        window_idx = idx[mask]
        if len(window_idx) == 0:
            continue
        d = dev.loc[window_idx]
        sig = pd.Series(0, index=window_idx, dtype=int)
        sig[d > 0.01] = -1
        sig[d < -0.01] = 1
        out.loc[window_idx] = sig
    return out.fillna(0).astype(int)
